Alright, here’s a clean and simple **VS Code–ready program** that runs fine in **both C and C++**, since it uses only common syntax.  
It converts **Decimal → Any Base** and **Any Base → Decimal**, using functions.

---

### ✅ Code: (works in both C and C++)
```cpp
#include <stdio.h>
#include <math.h>
#include <string.h>

int power(int base, int exp) {
    int result = 1;
    for (int i = 0; i < exp; i++)
        result *= base;
    return result;
}

void decimalToAnyBase(int num, int base) {
    char result[64];
    int index = 0;

    if (num == 0) {
        printf("0\n");
        return;
    }

    while (num > 0) {
        int rem = num % base;
        result[index++] = (rem < 10) ? rem + '0' : rem - 10 + 'A';
        num /= base;
    }

    printf("Result: ");
    for (int i = index - 1; i >= 0; i--)
        printf("%c", result[i]);
    printf("\n");
}

int anyBaseToDecimal(char numStr[], int base) {
    int len = strlen(numStr);
    int result = 0;

    for (int i = 0; i < len; i++) {
        char c = numStr[len - i - 1];
        int value = (c >= '0' && c <= '9') ? c - '0' : c - 'A' + 10;
        result += value * power(base, i);
    }

    return result;
}

int main() {
    int choice;
    printf("1. Decimal to Any Base\n2. Any Base to Decimal\nEnter choice: ");
    scanf("%d", &choice);

    if (choice == 1) {
        int num, base;
        printf("Enter decimal number: ");
        scanf("%d", &num);
        printf("Enter base (2–16): ");
        scanf("%d", &base);
        decimalToAnyBase(num, base);
    } else if (choice == 2) {
        char numStr[64];
        int base;
        printf("Enter number: ");
        scanf("%s", numStr);
        printf("Enter base (2–16): ");
        scanf("%d", &base);
        printf("Decimal: %d\n", anyBaseToDecimal(numStr, base));
    } else {
        printf("Invalid choice!\n");
    }

    return 0;
}
```

---

### ⚙️ How to Run
**In VS Code terminal:**
- For C:  
  ```bash
  gcc convert_base.c -o convert && ./convert
  ```
- For C++:  
  ```bash
  g++ convert_base.cpp -o convert && ./convert
  ```

---

### 🧠 Example Run
```
1. Decimal to Any Base
2. Any Base to Decimal
Enter choice: 1
Enter decimal number: 255
Enter base (2–16): 16
Result: FF
```

and  
```
Enter choice: 2
Enter number: FF
Enter base (2–16): 16
Decimal: 255
```

